// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.automationimport android.graphics.Bitmap/** * NOUS — Automation Provider Interface (Module 9 v1 — Step 9.2). * * Common interface implemented by both automation tiers: *  - [AccessibilityAutomationProvider] — Tier 1 (universal, 200-500ms per action) *  - [LadbAutomationProvider] — Tier 2 (Android 11+, 10ms per action, Step 9.4) * * The [AutomationEngine] (Step 9.5) auto-detects the best provider at runtime * and delegates all operations to it. If the primary provider fails, it falls * back to the secondary. * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Step 9.2</a> */interface AutomationProvider {    /** Unique name of this provider (e.g., "Accessibility", "LADB"). */    val providerName: String    /** The [AutomationMethod] this provider implements. */    val method: AutomationMethod    /** True if this provider is currently available + connected. */    fun isAvailable(): Boolean    /**     * Execute an automation operation.     *     * @param operation the operation to execute.     * @return the [AutomationResult] — Success, Failure, or NotSupported.     */    suspend fun execute(operation: AutomationOperation): AutomationResult    // ─── Convenience methods ──────────────────────────────────────────────    /** Tap at a screen coordinate. */    suspend fun tap(x: Float, y: Float): AutomationResult =        execute(AutomationOperation.Tap(x, y))    /** Swipe from one point to another. */    suspend fun swipe(        startX: Float,        startY: Float,        endX: Float,        endY: Float,        durationMs: Long = 300,    ): AutomationResult = execute(AutomationOperation.Swipe(startX, startY, endX, endY, durationMs))    /** Long-press at a coordinate. */    suspend fun longPress(x: Float, y: Float, durationMs: Long = 1000): AutomationResult =        execute(AutomationOperation.LongPress(x, y, durationMs))    /** Type text into the focused input field. */    suspend fun typeText(text: String): AutomationResult =        execute(AutomationOperation.TypeText(text))    /** Click a button by its visible text (e.g., "Send"). */    suspend fun clickButtonByText(text: String): AutomationResult =        execute(AutomationOperation.ClickButtonByText(text))    /** Click a button by its view ID. */    suspend fun clickButtonByViewId(viewId: String): AutomationResult =        execute(AutomationOperation.ClickButtonByViewId(viewId))    /** Press a hardware/system key (back, home, etc.). */    suspend fun pressKey(keyCode: Int): AutomationResult =        execute(AutomationOperation.PressKey(keyCode))    /** Take a screenshot. */    suspend fun takeScreenshot(): AutomationResult =        execute(AutomationOperation.TakeScreenshot)    /** Get the current UI tree. */    suspend fun getUiTree(): AutomationResult =        execute(AutomationOperation.GetUiTree)    /** Open an app by package name. */    suspend fun openApp(packageName: String): AutomationResult =        execute(AutomationOperation.OpenApp(packageName))    /** Scroll in a direction. */    suspend fun scroll(direction: ScrollDirection): AutomationResult =        execute(AutomationOperation.Scroll(direction))}